INSERT INTO public.curriculum_outcomes (code, substrand_code, letter, text, status) VALUES ('CREA.G6.APPREC.ANALYSIS_OF_CREATIVE_ART.e', 'CREA.G6.APPREC.ANALYSIS_OF_CREATIVE_ART', 'e', 'value analysing Creative Arts works drawn from various cultural backgrounds. 31 32', 'kicd_read') ON CONFLICT (code) DO NOTHING;
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G6.CREATI.STRING_MUSICAL_INSTRUMEN.INSTRUMENTS', 'CREA.G6.CREATI.STRING_MUSICAL_INSTRUMEN', 'creative_arts', 6, 'Identify indigenous Kenyan string instruments and how they are played', ARRAY['CREA.G6.CREATI.STRING_MUSICAL_INSTRUMEN.a']::text[], 'The child names the nyatiti and the orutu (Luo), the litungu (Luhya) and the obokano (Gusii) as string instruments, says that the nyatiti, litungu and obokano are plucked and the orutu is played with a bow, and does not put a drum or a flute in the string group. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the string instrument from a list","say how it is played","match an instrument to its community","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G6.CREATI.STRING_MUSICAL_INSTRUMEN.PARTS', 'CREA.G6.CREATI.STRING_MUSICAL_INSTRUMEN', 'creative_arts', 6, 'Describe the function of the parts of a string instrument', ARRAY['CREA.G6.CREATI.STRING_MUSICAL_INSTRUMEN.b']::text[], 'The child says the strings vibrate to make the sound, the hollow body makes the sound louder, the bridge holds the strings above the body and passes their shaking to it, the pegs tighten or loosen the strings to tune them, a tighter string gives a higher sound, and the bow of the orutu rubs the string to make it sound. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G6.RUBRIC.1.1), never as a phone question: c) make a fiddle using recyclable materials.', '["name the part from its job","say what the strings, the body and the pegs each do","say how to raise the sound","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G6.CREATI.STRING_MUSICAL_INSTRUMEN.STIPPLING', 'CREA.G6.CREATI.STRING_MUSICAL_INSTRUMEN', 'creative_arts', 6, 'Say what stippling is and how it shows light and dark', ARRAY['CREA.G6.CREATI.STRING_MUSICAL_INSTRUMEN.d']::text[], 'The child says stippling is drawing a picture with many small dots, that dots packed close together look dark and dots spaced apart look light, that no lines or smudging are used, and puts the steps in order: light pencil outline, dots with a pen, closer dots for dark parts. This is the knowledge half of outcomes d and e; drawing is practical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G6.RUBRIC.1.1), never as a phone question: e) draw a picture of a musical instrument using stippling technique.', '["pick the picture made with dots","say how dots make dark and light","put the stippling steps in order","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G6.CREATI.PAINTING_AND_COLLAGE.COLOUR_WHEEL', 'CREA.G6.CREATI.PAINTING_AND_COLLAGE', 'creative_arts', 6, 'Sort colours into primary, secondary and tertiary, warm and cool', ARRAY['CREA.G6.CREATI.PAINTING_AND_COLLAGE.a']::text[], 'The child names red, yellow and blue as primary colours, says orange (red and yellow), green (yellow and blue) and violet (blue and red) are secondary colours, that a tertiary colour is a primary mixed with the secondary beside it, and sorts red, orange and yellow as warm and blue, green and violet as cool. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["name the primary colours","say which two colours make a secondary colour","sort a colour as warm or cool","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G6.CREATI.PAINTING_AND_COLLAGE.TECHNIQUES', 'CREA.G6.CREATI.PAINTING_AND_COLLAGE', 'creative_arts', 6, 'Say what a still life, a brush stroke, a mat mount and a collage are', ARRAY['CREA.G6.CREATI.PAINTING_AND_COLLAGE.b', 'CREA.G6.CREATI.PAINTING_AND_COLLAGE.c', 'CREA.G6.CREATI.PAINTING_AND_COLLAGE.d']::text[], 'The child says a still life is a painting of objects that do not move (a bowl of fruit, a jug), that brush strokes are the marks the brush leaves, that a mat is a card border put round a painting when it is mounted for display, and that a collage is made by gluing pieces of paper, cloth or other materials on a surface. Painting and mounting are practical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G6.RUBRIC.1.1), never as a phone question: b) paint a still life composition using brush stroke technique; c) mount the painting using mat technique for display; d) create a collage composition to apply the characteristics.', '["say what a still life is","pick the use of a mat","say how a collage is made","put the mounting steps in order"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G6.CREATI.VOLLEYBALL.SKILLS', 'CREA.G6.CREATI.VOLLEYBALL', 'creative_arts', 6, 'Describe the under-arm serve and the dig pass in volleyball', ARRAY['CREA.G6.CREATI.VOLLEYBALL.a']::text[], 'The child says a team has six players on the court, the under-arm serve is struck from below the waist with the fist or open hand so that the ball goes over the net, a dig pass uses the joined forearms (or one hand) to lift a low ball, and the ball must not be caught, kicked or held. This is the knowledge half of outcomes a to c; playing is practical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G6.RUBRIC.1.1), never as a phone question: b) perform under-arm service for skill acquisition; c) execute single hand dig pass in volleyball for skill acquisition.', '["pick the way to serve","pick the part of the body used to dig","say a rule of the game","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G6.CREATI.RHYTHM_AND_PATTERN_MAKIN.NOTES', 'CREA.G6.CREATI.RHYTHM_AND_PATTERN_MAKIN', 'creative_arts', 6, 'Say how many beats each note and rest lasts and what a three-beat pattern is', ARRAY['CREA.G6.CREATI.RHYTHM_AND_PATTERN_MAKIN.a', 'CREA.G6.CREATI.RHYTHM_AND_PATTERN_MAKIN.b']::text[], 'The child says a semibreve lasts four beats, a minim two, a crotchet one and a quaver half a beat (two quavers make one beat), that a rest is a silence of the same length as its note, and that in a three-beat pattern each bar adds up to three beats. Clapping and improvising are practical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G6.RUBRIC.1.1), never as a phone question: b) compose a rhythm using a combination of musical notes and their rests; c) improvise a rhythm in three- beat pattern on a percussion instrument.', '["say how many beats a note lasts","say what a rest means","count a three-beat bar","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G6.CREATI.RHYTHM_AND_PATTERN_MAKIN.PRINTING', 'CREA.G6.CREATI.RHYTHM_AND_PATTERN_MAKIN', 'creative_arts', 6, 'Put the steps of block printing in order and say what a repeat pattern is', ARRAY['CREA.G6.CREATI.RHYTHM_AND_PATTERN_MAKIN.d', 'CREA.G6.CREATI.RHYTHM_AND_PATTERN_MAKIN.e']::text[], 'The child says a motif is a single shape used in a design (a circle, a triangle or a square), puts the steps in order (draw the motif on the block, cut it away so the motif stands up, roll ink on the block, press it on the paper, lift it, repeat in a row) and says a repeat pattern uses the same motif over and over in even rows. Cutting and printing are practical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G6.RUBRIC.1.1), never as a phone question: d) prepare a block with a geometrical motif for printing a pattern; e) print a full repeat pattern using a block for rhythm acquisition.', '["put the steps in order","say what a motif is","say what a full repeat pattern is","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G6.CREATI.WEAVING.PLAIN_WEAVE', 'CREA.G6.CREATI.WEAVING', 'creative_arts', 6, 'Say what the warp and weft are and how a plain weave goes', ARRAY['CREA.G6.CREATI.WEAVING.a', 'CREA.G6.CREATI.WEAVING.b']::text[], 'The child says the warp is the set of threads held tight on the loom and the weft is the thread woven across them, that plain weave goes over one warp and under the next and the next row does the opposite, that a serrated card loom has notches to hold the warp, and names suitable materials (raffia, sisal, strips of cloth, wool). Weaving a mat is practical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G6.RUBRIC.1.1), never as a phone question: b) prepare materials and tools for weaving; c) weave a mat using plain weave on a serrated card loom.', '["pick the warp or the weft","say how a plain weave goes","pick the materials","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G6.CREATI.GYMNASTICS.CARTWHEEL', 'CREA.G6.CREATI.GYMNASTICS', 'creative_arts', 6, 'Describe the cartwheel and put the three-action sequence in order', ARRAY['CREA.G6.CREATI.GYMNASTICS.a', 'CREA.G6.CREATI.GYMNASTICS.c']::text[], 'The child says a cartwheel is a sideways turn with straight arms, in the order hand, hand, foot, foot, with the legs straight and wide, that a forward roll tucks the chin and rounds the back, that a swan balance stands on one leg with the other leg lifted behind and arms out, and puts the sequence cartwheel, forward roll, swan balance in order. Performing is practical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G6.RUBRIC.1.1), never as a phone question: b) perform the cartwheel skill in gymnastics; c) perform 3-action sequence in cartwheel, forward roll and swan balance in gymnastics.', '["put the cartwheel hands and feet in order","say what makes a good cartwheel","put the sequence in order","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G6.CREATI.MELODY.SOLFA', 'CREA.G6.CREATI.MELODY', 'creative_arts', 6, 'Say the sol-fa syllables in order, up and down, and the hand signs for doh and ti', ARRAY['CREA.G6.CREATI.MELODY.a', 'CREA.G6.CREATI.MELODY.b', 'CREA.G6.CREATI.MELODY.c']::text[], 'The child says the syllables going up are doh, re, mi, fah, soh, lah, ti, doh1 and going down are doh1, ti, lah, soh, fah, mi, re, doh, that doh1 sounds higher than doh, that the hand sign for doh is a closed fist and for ti a finger pointing up. Singing, signing and composing are practical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G6.RUBRIC.1.1), never as a phone question: a) sing the sol-fa syllables doh to doh1 ascending and descending; b) perform the sol-fa ladder using Kodaly hand signs; d) compose short melodies within the range of doh to doh1; e) write the sol-fa syllables using calligraphy lettering.', '["say the next syllable","say the syllables going down","say which sounds higher","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G6.PERFOR.ATHLETICS.JUMPS', 'CREA.G6.PERFOR.ATHLETICS', 'creative_arts', 6, 'Describe the long jump and the high jump', ARRAY['CREA.G6.PERFOR.ATHLETICS.a']::text[], 'The child puts the long jump phases in order (run-up, take-off from one foot, flight, landing in the pit), says the sail is holding the legs together and forward in the air, that the high jump starts from an angled run-up, takes off on one foot, goes over the bar in a scissors action (one leg and then the other) and lands on the mat, and that a long jump is measured to the nearest mark in the sand. Performing is practical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G6.RUBRIC.2.1), never as a phone question: b) perform the sail technique in Long jump for skills acquisition; c) perform the scissors technique in High jump for skills acquisition.', '["put the phases in order","say how to take off","say what the sail and the scissors are","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G6.PERFOR.DESCANT_RECORDER.TECHNIQUE', 'CREA.G6.PERFOR.DESCANT_RECORDER', 'creative_arts', 6, 'Say how to hold and play a descant recorder', ARRAY['CREA.G6.PERFOR.DESCANT_RECORDER.a', 'CREA.G6.PERFOR.DESCANT_RECORDER.b']::text[], 'The child says the left hand is on the top holes and the right hand below, the thumb covers the hole at the back, the finger pads cover the holes fully, the player blows gently and tongues each note with "too", and covering more holes gives a lower sound. The national anthem begins "Ee Mungu nguvu yetu". Playing is practical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G6.RUBRIC.2.1), never as a phone question: a) play notes C to D1 on the descant recorder with appropriate playing techniques; b) play a melody within the range of C to D1on the descant recorder; c) play the main melody of the Kenya National Anthem on the descant recorder.', '["pick the way to hold it","say how to blow and tongue","say what covered holes do","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G6.PERFOR.INDIGENOUS_KENYAN_INSTRU.ENSEMBLE', 'CREA.G6.PERFOR.INDIGENOUS_KENYAN_INSTRU', 'creative_arts', 6, 'Say the kinds of Kenyan ensemble and what players do in an ensemble', ARRAY['CREA.G6.PERFOR.INDIGENOUS_KENYAN_INSTRU.a', 'CREA.G6.PERFOR.INDIGENOUS_KENYAN_INSTRU.b']::text[], 'The child sorts drums, shakers and rattles as percussion, horns and flutes as wind and the nyatiti and litungu as string, says an ensemble can be of one kind or mixed, and says that players in an ensemble keep a steady beat, listen to each other, balance their loudness and start and stop together. Playing is practical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G6.RUBRIC.2.1), never as a phone question: c) play a selected instrument in an ensemble using appropriate techniques.', '["sort an instrument into percussion, wind or string","pick what a good ensemble player does","say why players listen","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G6.PERFOR.INDIGENOUS_KENYAN_CRAFT_.SLAB', 'CREA.G6.PERFOR.INDIGENOUS_KENYAN_CRAFT_', 'creative_arts', 6, 'Put the steps of the slab technique in order', ARRAY['CREA.G6.PERFOR.INDIGENOUS_KENYAN_CRAFT_.a', 'CREA.G6.PERFOR.INDIGENOUS_KENYAN_CRAFT_.c']::text[], 'The child says a slab is a flat sheet of clay rolled out to an even thickness, puts the steps in order (roll the slab, cut the pieces, score and wet the edges, press them together, smooth, dry slowly, decorate), says joining needs scratching and slip (clay mixed with water) and that clay dried too fast cracks. Modelling a vase is practical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G6.RUBRIC.2.1), never as a phone question: b) model a vase using slab technique for expression; c) decorate a modelled item for aesthetic enhancement.', '["put the steps in order","say how to join two pieces","say how to dry and decorate","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G6.PERFOR.SWIMMING.BREASTSTROKE', 'CREA.G6.PERFOR.SWIMMING', 'creative_arts', 6, 'Describe the body position, arm and leg action of breaststroke', ARRAY['CREA.G6.PERFOR.SWIMMING.a_']::text[], 'The child says the body lies flat and face down, the arms sweep out, in and forward, the legs do a frog kick (knees bend, feet turn out, kick back and together), the head lifts to breathe at the end of the arm pull and the swimmer glides, and that a child swims only with a trained adult watching. Swimming is practical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G6.RUBRIC.2.1), never as a phone question: b) perform breaststroke in swimming for skill acquisition.', '["say how the body lies","say how the legs kick","say when to breathe","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G6.APPREC.ANALYSIS_OF_CREATIVE_ART.ELEMENTS', 'CREA.G6.APPREC.ANALYSIS_OF_CREATIVE_ART', 'creative_arts', 6, 'Name the elements of music in a song and the message it carries', ARRAY['CREA.G6.APPREC.ANALYSIS_OF_CREATIVE_ART.b', 'CREA.G6.APPREC.ANALYSIS_OF_CREATIVE_ART.c']::text[], 'The child says pitch is how high or low a sound is, tempo is how fast or slow, dynamics is how loud or soft, rhythm is the pattern of long and short sounds, melody is the tune, and that a message is what the words of a song teach or say (about unity, work, peace, care of the environment). Judging a real song is practical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["name the element from its job","say what the message of a song is","sort a song''s message","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G6.APPREC.ANALYSIS_OF_CREATIVE_ART.CATALOGUE', 'CREA.G6.APPREC.ANALYSIS_OF_CREATIVE_ART', 'creative_arts', 6, 'Say what a catalogue of artworks lists and why', ARRAY['CREA.G6.APPREC.ANALYSIS_OF_CREATIVE_ART.a']::text[], 'The child says a catalogue is a list of the artworks in an exhibition, each entry gives a number, the title, the artist, the material and the size, and it helps visitors find and understand the works. Making a catalogue (outcome a) is practical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G6.RUBRIC.3.1), never as a phone question: a) create a catalogue of the exhibited artworks.', '["say what a catalogue is for","pick what an entry lists","put the entries in order","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
