INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G6.CREATI.STRING_MUSICAL_INSTRUMEN.STIPPLING', 'CREA.G5.CREATI.WIND_MUSICAL_INSTRUMENTS.ETCHING', 'skill', 'essential', 'Cross-hatching for dark areas (Grade 5) is shading by lines; stippling shades with dots. Proposed, to confirm by a CBC Creative Arts teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
