INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G6.PERFOR.INDIGENOUS_KENYAN_CRAFT_.SLAB', 'CREA.G4.CREATI.MELODY.CLAY', 'skill', 'essential', 'Slab and coil steps (Grade 4 melody plaques) are used again for a vase. Proposed, to confirm by a CBC Creative Arts teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G6.PERFOR.INDIGENOUS_KENYAN_CRAFT_.SLAB', 'CREA.G3.PERFOR.MODELLING_AND_ORNAMENT_M.BEADS', 'skill', 'helpful', 'Decorating modelled beads (Grade 3) is the first decoration of clay. Proposed, to confirm by a CBC Creative Arts teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G6.PERFOR.SWIMMING.BREASTSTROKE', 'CREA.G5.PERFOR.SWIMMING.a_', 'outcome', 'essential', 'Grade 5 Creative Arts introduced it. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G6.PERFOR.SWIMMING.BREASTSTROKE', 'CREA.G5.PERFOR.SWIMMING.CRAWL', 'skill', 'essential', 'The flat body position of the front crawl (Grade 5) is also used in breaststroke. Proposed, to confirm by a CBC Creative Arts teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G6.PERFOR.SWIMMING.BREASTSTROKE', 'CREA.G5.PERFOR.SWIMMING.POOL_SAFETY', 'skill', 'essential', 'Pool safety (Grade 5) comes before every stroke. Proposed, to confirm by a CBC Creative Arts teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G6.APPREC.ANALYSIS_OF_CREATIVE_ART.ELEMENTS', 'CREA.G5.APPREC.ANALYSIS_OF_CREATIVE_ART.a', 'outcome', 'essential', 'Grade 5 Creative Arts introduced it. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G6.APPREC.ANALYSIS_OF_CREATIVE_ART.ELEMENTS', 'CREA.G4.PERFOR.SONGS.PERFTERMS', 'skill', 'essential', 'Pitch, tempo and dynamics (Grade 4) are the elements of music named here. Proposed, to confirm by a CBC Creative Arts teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G6.APPREC.ANALYSIS_OF_CREATIVE_ART.CATALOGUE', 'CREA.G6.APPREC.ANALYSIS_OF_CREATIVE_ART.ELEMENTS', 'skill', 'essential', 'This skill builds on it. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G6.APPREC.ANALYSIS_OF_CREATIVE_ART.CATALOGUE', 'CREA.G4.APPREC.ANALYSIS_OF_CREATIVE_ART.PORTFOLIO', 'skill', 'essential', 'Labelling work with name, title and date (Grade 4 portfolio) is a catalogue entry. Proposed, to confirm by a CBC Creative Arts teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.STRING_MUSICAL_INSTRUMEN.INSTRUMENTS.M_SM_WIND_AS_STRING', 'CREA.G6.CREATI.STRING_MUSICAL_INSTRUMEN.INSTRUMENTS', 'Puts a wind or a drum instrument in the string group.', '{"question":"Which of these is a string instrument?","wrong_answer":"The nzumari","correct_answer":"The nyatiti"}'::jsonb, 'The child knows it is an indigenous instrument and does not ask how the sound is made.', 'Offer "The nzumari" next to the right answer and ask the question again in a new context.', 'Ask: what do you do to make the sound? Pluck, bow, blow or hit? Sort five instruments by that one question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.STRING_MUSICAL_INSTRUMEN.INSTRUMENTS.M_SM_PLAY', 'CREA.G6.CREATI.STRING_MUSICAL_INSTRUMEN.INSTRUMENTS', 'Says the orutu is plucked, or the nyatiti is played with a bow.', '{"question":"How is the orutu played?","wrong_answer":"It is plucked with the fingers","correct_answer":"It is played with a bow"}'::jsonb, 'The child thinks all string instruments are plucked.', 'Offer "It is plucked with the fingers" next to the right answer and ask the question again in a new context.', 'Look at pictures: the orutu has one string and a bow, the nyatiti has many strings and no bow.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.STRING_MUSICAL_INSTRUMEN.INSTRUMENTS.M_SM_COMMUNITY', 'CREA.G6.CREATI.STRING_MUSICAL_INSTRUMEN.INSTRUMENTS', 'Gives the nyatiti to the Luhya, mixing it with the litungu, another lyre.', '{"question":"The nyatiti belongs to which people?","wrong_answer":"The Luhya","correct_answer":"The Luo"}'::jsonb, 'The nyatiti and the litungu are both lyres with many strings, so the child mixes their communities.', 'Offer "The Luhya" next to the right answer and ask the question again in a new context.', 'Make a matching card: instrument, community, how it is played.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.STRING_MUSICAL_INSTRUMEN.PARTS.M_SP_BODY', 'CREA.G6.CREATI.STRING_MUSICAL_INSTRUMEN.PARTS', 'Says the strings make the sound louder, or the body makes the sound.', '{"question":"What does the hollow body of a string instrument do?","wrong_answer":"It makes the strings vibrate","correct_answer":"It makes the sound louder"}'::jsonb, 'The child thinks the biggest part makes the sound.', 'Offer "It makes the strings vibrate" next to the right answer and ask the question again in a new context.', 'Pluck a string held in the air and then over a tin: hear the tin make it louder.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.STRING_MUSICAL_INSTRUMEN.PARTS.M_SP_PEG', 'CREA.G6.CREATI.STRING_MUSICAL_INSTRUMEN.PARTS', 'Says the pegs make the sound or play the notes.', '{"question":"What are the pegs for?","wrong_answer":"To pluck the strings","correct_answer":"To tighten or loosen the strings to tune them"}'::jsonb, 'The child does not know tuning.', 'Offer "To pluck the strings" next to the right answer and ask the question again in a new context.', 'Tighten a rubber band and pluck: hear it rise.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.STRING_MUSICAL_INSTRUMEN.PARTS.M_SP_TIGHT', 'CREA.G6.CREATI.STRING_MUSICAL_INSTRUMEN.PARTS', 'Says a looser string gives a higher sound.', '{"question":"Which string gives a higher sound?","wrong_answer":"A looser, slacker string","correct_answer":"A tighter string"}'::jsonb, 'The child thinks looser strings move more freely and sound higher.', 'Offer "A looser, slacker string" next to the right answer and ask the question again in a new context.', 'Tighten and loosen a rubber band and listen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.STRING_MUSICAL_INSTRUMEN.STIPPLING.M_ST_LINES', 'CREA.G6.CREATI.STRING_MUSICAL_INSTRUMEN.STIPPLING', 'Says stippling uses lines or hatching.', '{"question":"What is stippling?","wrong_answer":"Drawing with many lines","correct_answer":"Drawing with many small dots"}'::jsonb, 'The child mixes stippling with hatching.', 'Offer "Drawing with many lines" next to the right answer and ask the question again in a new context.', 'Draw one patch with dots and one with lines and name them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.STRING_MUSICAL_INSTRUMEN.STIPPLING.M_ST_DARK', 'CREA.G6.CREATI.STRING_MUSICAL_INSTRUMEN.STIPPLING', 'Says dots far apart look darker.', '{"question":"How do you make a part of a stippled picture look dark?","wrong_answer":"Put the dots far apart","correct_answer":"Put the dots close together"}'::jsonb, 'The child links more space with more dark.', 'Offer "Put the dots far apart" next to the right answer and ask the question again in a new context.', 'Make two squares, one with close dots and one with spaced dots, and ask which looks darker.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.STRING_MUSICAL_INSTRUMEN.STIPPLING.M_ST_SMEAR', 'CREA.G6.CREATI.STRING_MUSICAL_INSTRUMEN.STIPPLING', 'Says stippling is smudging or blending.', '{"question":"Which step belongs to stippling?","wrong_answer":"Smudge the ink with a finger","correct_answer":"Make dots with a pen"}'::jsonb, 'The child mixes the shading methods.', 'Offer "Smudge the ink with a finger" next to the right answer and ask the question again in a new context.', 'Compare stippling and smudged charcoal.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.STRING_MUSICAL_INSTRUMEN.INSTRUMENTS.M_CA6_SM_OBOKANO_SMALL', 'CREA.G6.CREATI.STRING_MUSICAL_INSTRUMEN.INSTRUMENTS', 'Thinks the obokano is a small hand-held fiddle.', '{"question":"Is the obokano a small fiddle or a large lyre?","wrong_answer":"a small fiddle","correct_answer":"a large lyre"}'::jsonb, 'The child knows it has strings and pictures the orutu.', 'Offer "a small fiddle" next to the right answer and ask the question again in a new context.', 'Show the size of the obokano next to a learner.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.STRING_MUSICAL_INSTRUMEN.PARTS.M_CA6_SP_THICK_HIGH', 'CREA.G6.CREATI.STRING_MUSICAL_INSTRUMEN.PARTS', 'Thinks a thicker string gives a higher note.', '{"question":"Which string gives the lower note: a thick one or a thin one?","wrong_answer":"the thin one","correct_answer":"the thick one"}'::jsonb, 'Thick looks strong and loud, so the child links it with high.', 'Offer "the thin one" next to the right answer and ask the question again in a new context.', 'Pluck a thick and a thin rubber band on a tin.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.STRING_MUSICAL_INSTRUMEN.STIPPLING.M_CA6_ST_BIG_BLOBS', 'CREA.G6.CREATI.STRING_MUSICAL_INSTRUMEN.STIPPLING', 'Makes big blobs instead of small dots, so tones look patchy.', '{"question":"Should stippling dots be big blobs or small dots?","wrong_answer":"big blobs","correct_answer":"small dots, closer together for darker areas"}'::jsonb, 'The child wants to fill the page quickly.', 'Offer "big blobs" next to the right answer and ask the question again in a new context.', 'Stipple a strip with fine dots and one with blobs; compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.PAINTING_AND_COLLAGE.COLOUR_WHEEL.M_CW_SECONDARY_PRIMARY', 'CREA.G6.CREATI.PAINTING_AND_COLLAGE.COLOUR_WHEEL', 'Says green or orange is a primary colour.', '{"question":"Which of these is a primary colour?","wrong_answer":"Green","correct_answer":"Blue"}'::jsonb, 'The child names the colours he sees most often.', 'Offer "Green" next to the right answer and ask the question again in a new context.', 'Mix red and yellow to get orange, and ask whether red can be made by mixing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.PAINTING_AND_COLLAGE.COLOUR_WHEEL.M_CW_MIX', 'CREA.G6.CREATI.PAINTING_AND_COLLAGE.COLOUR_WHEEL', 'Mixes red and blue for green, taking the wrong pair from the wheel.', '{"question":"Which two colours make green?","wrong_answer":"Red and blue","correct_answer":"Yellow and blue"}'::jsonb, 'The child remembers green is mixed from two primaries but not which two.', 'Offer "Red and blue" next to the right answer and ask the question again in a new context.', 'Mix the three pairs of primaries on paper.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.PAINTING_AND_COLLAGE.COLOUR_WHEEL.M_CW_WARM', 'CREA.G6.CREATI.PAINTING_AND_COLLAGE.COLOUR_WHEEL', 'Sorts a cool colour as warm or a warm colour as cool.', '{"question":"Which colour is warm?","wrong_answer":"Blue","correct_answer":"Orange"}'::jsonb, 'The child sorts by how bright the colour is.', 'Offer "Blue" next to the right answer and ask the question again in a new context.', 'Link warm colours to fire and cool colours to water and sky.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.PAINTING_AND_COLLAGE.TECHNIQUES.M_PT_STILL', 'CREA.G6.CREATI.PAINTING_AND_COLLAGE.TECHNIQUES', 'Says a still life shows people or animals moving.', '{"question":"What is a still life?","wrong_answer":"A painting of people moving","correct_answer":"A painting of objects that do not move"}'::jsonb, 'The child hears "life" and thinks of living things.', 'Offer "A painting of people moving" next to the right answer and ask the question again in a new context.', 'Set a bowl of fruit and a jug on a table and ask what could move.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.PAINTING_AND_COLLAGE.TECHNIQUES.M_PT_MAT', 'CREA.G6.CREATI.PAINTING_AND_COLLAGE.TECHNIQUES', 'Says a mat is a carpet or a floor covering.', '{"question":"What is a mat used for when mounting a painting?","wrong_answer":"To stand on","correct_answer":"To make a card border round the painting"}'::jsonb, 'The child knows only the word mat for a floor mat.', 'Offer "To stand on" next to the right answer and ask the question again in a new context.', 'Show a framed picture with a card border.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.PAINTING_AND_COLLAGE.TECHNIQUES.M_PT_COLLAGE', 'CREA.G6.CREATI.PAINTING_AND_COLLAGE.TECHNIQUES', 'Says a collage is drawn with a pencil or painted.', '{"question":"How is a collage made?","wrong_answer":"By drawing with a pencil","correct_answer":"By gluing pieces of paper or cloth on a surface"}'::jsonb, 'The child mixes collage with drawing.', 'Offer "By drawing with a pencil" next to the right answer and ask the question again in a new context.', 'Tear paper pieces and glue them to make a picture.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.PAINTING_AND_COLLAGE.COLOUR_WHEEL.M_CA6_CW_TERTIARY_TWO_SECONDARY', 'CREA.G6.CREATI.PAINTING_AND_COLLAGE.COLOUR_WHEEL', 'Thinks a tertiary colour is made from two secondary colours.', '{"question":"How is a tertiary colour made?","wrong_answer":"mix two secondary colours","correct_answer":"mix a primary with the secondary next to it"}'::jsonb, 'The child expects the next level to mix two of the level before.', 'Offer "mix two secondary colours" next to the right answer and ask the question again in a new context.', 'Mix yellow and green on the palette: yellow-green.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.PAINTING_AND_COLLAGE.TECHNIQUES.M_CA6_PT_COLLAGE_ONE_MATERIAL', 'CREA.G6.CREATI.PAINTING_AND_COLLAGE.TECHNIQUES', 'Thinks a collage uses only one kind of paper.', '{"question":"What can a collage be made from?","wrong_answer":"only coloured paper","correct_answer":"many materials: paper, fabric, seeds, leaves"}'::jsonb, 'The child has seen collages from paper only.', 'Offer "only coloured paper" next to the right answer and ask the question again in a new context.', 'Show a collage with fabric, seeds and paper.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.VOLLEYBALL.SKILLS.M_VB_FEET', 'CREA.G6.CREATI.VOLLEYBALL.SKILLS', 'Says the ball may be kicked, caught or held.', '{"question":"In volleyball, what must a player not do with the ball?","wrong_answer":"Hit it with the forearms","correct_answer":"Catch it and hold it"}'::jsonb, 'The child mixes volleyball with football or netball.', 'Offer "Hit it with the forearms" next to the right answer and ask the question again in a new context.', 'Play a short game where catching the ball loses the point.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.VOLLEYBALL.SKILLS.M_VB_DIG', 'CREA.G6.CREATI.VOLLEYBALL.SKILLS', 'Says the dig is played with the head, taking it for heading in football.', '{"question":"Which part of the body is used for a dig pass?","wrong_answer":"The head","correct_answer":"The joined forearms"}'::jsonb, 'The child knows heading a ball from football and expects the same in volleyball.', 'Offer "The head" next to the right answer and ask the question again in a new context.', 'Practise with a soft ball: hold the forearms together and lift a low ball.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.VOLLEYBALL.SKILLS.M_VB_SERVE', 'CREA.G6.CREATI.VOLLEYBALL.SKILLS', 'Says the under-arm serve is struck from above the head.', '{"question":"Where is the ball when it is struck in an under-arm serve?","wrong_answer":"Above the head","correct_answer":"Below the waist"}'::jsonb, 'The child mixes the under-arm serve with the overhead serve.', 'Offer "Above the head" next to the right answer and ask the question again in a new context.', 'Compare the two serves with a soft ball.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.VOLLEYBALL.SKILLS.M_CA6_VB_SWING_ARMS', 'CREA.G6.CREATI.VOLLEYBALL.SKILLS', 'Swings the arms high above the shoulders in a dig pass.', '{"question":"In a dig pass, should you swing your arms up high?","wrong_answer":"yes","correct_answer":"no; keep arms straight and lift from the legs"}'::jsonb, 'The child wants power and swings the arms.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Dig with straight arms and a small leg push.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.RHYTHM_AND_PATTERN_MAKIN.NOTES.M_RN_VALUE', 'CREA.G6.CREATI.RHYTHM_AND_PATTERN_MAKIN.NOTES', 'Gives a crotchet two beats, taking the minim''s value.', '{"question":"How many beats does a crotchet last?","wrong_answer":"Two beats","correct_answer":"One beat"}'::jsonb, 'The minim and crotchet look alike except for the hollow head, so the child swaps them.', 'Offer "Two beats" next to the right answer and ask the question again in a new context.', 'Clap crotchets, minims and quavers while counting.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.RHYTHM_AND_PATTERN_MAKIN.NOTES.M_RN_REST', 'CREA.G6.CREATI.RHYTHM_AND_PATTERN_MAKIN.NOTES', 'Says a rest is clapped or played as a note.', '{"question":"What do you do at a rest?","wrong_answer":"Clap one beat","correct_answer":"Stay silent for its length"}'::jsonb, 'The child thinks every beat must be heard.', 'Offer "Clap one beat" next to the right answer and ask the question again in a new context.', 'Clap a pattern with a rest and stay silent on it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.RHYTHM_AND_PATTERN_MAKIN.NOTES.M_RN_BAR', 'CREA.G6.CREATI.RHYTHM_AND_PATTERN_MAKIN.NOTES', 'Says a three-beat pattern has three notes whatever their length.', '{"question":"What does a three-beat bar add up to?","wrong_answer":"Three notes","correct_answer":"Three beats"}'::jsonb, 'The child counts notes and not beats.', 'Offer "Three notes" next to the right answer and ask the question again in a new context.', 'Write a bar of one minim and one crotchet and count it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.RHYTHM_AND_PATTERN_MAKIN.PRINTING.M_BP_ORDER', 'CREA.G6.CREATI.RHYTHM_AND_PATTERN_MAKIN.PRINTING', 'Puts the steps in the wrong order, such as printing before inking.', '{"question":"What comes first in block printing?","wrong_answer":"Press the block on the paper","correct_answer":"Draw and cut the motif on the block"}'::jsonb, 'The child thinks only of the printing.', 'Offer "Press the block on the paper" next to the right answer and ask the question again in a new context.', 'Write each step on a card and put the cards in order.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.RHYTHM_AND_PATTERN_MAKIN.PRINTING.M_BP_INK', 'CREA.G6.CREATI.RHYTHM_AND_PATTERN_MAKIN.PRINTING', 'Says ink is put on the paper before the block is pressed.', '{"question":"Where is the ink put?","wrong_answer":"On the paper","correct_answer":"On the block"}'::jsonb, 'The child does not see the block as the stamp.', 'Offer "On the paper" next to the right answer and ask the question again in a new context.', 'Press a clean block and an inked block on paper and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.RHYTHM_AND_PATTERN_MAKIN.PRINTING.M_BP_REPEAT', 'CREA.G6.CREATI.RHYTHM_AND_PATTERN_MAKIN.PRINTING', 'Says a repeat pattern has a different motif each time or is placed at random.', '{"question":"What is a full repeat pattern?","wrong_answer":"Different motifs placed at random","correct_answer":"The same motif repeated in even rows"}'::jsonb, 'The child mixes repeat with random.', 'Offer "Different motifs placed at random" next to the right answer and ask the question again in a new context.', 'Print one motif in a row and then in many rows.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.RHYTHM_AND_PATTERN_MAKIN.NOTES.M_CA6_RN_DOTTED', 'CREA.G6.CREATI.RHYTHM_AND_PATTERN_MAKIN.NOTES', 'Thinks a dotted minim lasts two beats like a plain minim.', '{"question":"How many beats does a dotted minim last?","wrong_answer":"two","correct_answer":"three"}'::jsonb, 'The child does not know the dot adds half the value.', 'Offer "two" next to the right answer and ask the question again in a new context.', 'Clap a minim (2) then add half (1).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.RHYTHM_AND_PATTERN_MAKIN.PRINTING.M_CA6_BP_MIRROR', 'CREA.G6.CREATI.RHYTHM_AND_PATTERN_MAKIN.PRINTING', 'Cuts a letter on the block the right way round, so it prints backwards.', '{"question":"You cut the letter K on a block. How will it print?","wrong_answer":"the right way round","correct_answer":"backwards, as a mirror image"}'::jsonb, 'The child does not know a print is a mirror of the block.', 'Offer "the right way round" next to the right answer and ask the question again in a new context.', 'Print a block with a cut letter and look.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.WEAVING.PLAIN_WEAVE.M_WV_WARP', 'CREA.G6.CREATI.WEAVING.PLAIN_WEAVE', 'Mixes up the warp and the weft.', '{"question":"Which threads are held tight on the loom?","wrong_answer":"The weft","correct_answer":"The warp"}'::jsonb, 'The child has not fixed the two names.', 'Offer "The weft" next to the right answer and ask the question again in a new context.', 'Make a loom and name the threads as they are used: warp stays, weft travels.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.WEAVING.PLAIN_WEAVE.M_WV_PATTERN', 'CREA.G6.CREATI.WEAVING.PLAIN_WEAVE', 'Says plain weave goes over two and under two.', '{"question":"How does a plain weave go?","wrong_answer":"Over two warp threads and under two","correct_answer":"Over one warp thread and under the next"}'::jsonb, 'The child mixes plain weave with twill.', 'Offer "Over two warp threads and under two" next to the right answer and ask the question again in a new context.', 'Weave a strip over one and under one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.WEAVING.PLAIN_WEAVE.M_WV_SAME_ROW', 'CREA.G6.CREATI.WEAVING.PLAIN_WEAVE', 'Says the next row repeats the first row.', '{"question":"How does the second row of a plain weave start?","wrong_answer":"The same as the first row","correct_answer":"The opposite of the first row"}'::jsonb, 'The child does not see why the rows alternate.', 'Offer "The same as the first row" next to the right answer and ask the question again in a new context.', 'Weave two rows the same and see the strip fall apart.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.WEAVING.PLAIN_WEAVE.M_CA6_WV_PULL_TIGHT', 'CREA.G6.CREATI.WEAVING.PLAIN_WEAVE', 'Pulls the weft so tight that the edges of the mat curve inward.', '{"question":"Why must the weft not be pulled too tight?","wrong_answer":"tight is always stronger","correct_answer":"it pulls the edges in and the mat loses its shape"}'::jsonb, 'The child thinks tighter is always better.', 'Offer "tight is always stronger" next to the right answer and ask the question again in a new context.', 'Weave two rows, one too tight; see the waist form.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.GYMNASTICS.CARTWHEEL.M_CW_ORDER', 'CREA.G6.CREATI.GYMNASTICS.CARTWHEEL', 'Puts the feet before the hands.', '{"question":"In a cartwheel, which touch the ground first?","wrong_answer":"The feet","correct_answer":"The hands, one after the other"}'::jsonb, 'The child thinks of a roll.', 'Offer "The feet" next to the right answer and ask the question again in a new context.', 'Walk through the order slowly: hand, hand, foot, foot.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.GYMNASTICS.CARTWHEEL.M_CW_BENT', 'CREA.G6.CREATI.GYMNASTICS.CARTWHEEL', 'Says the arms and legs should be bent.', '{"question":"How should the arms be in a cartwheel?","wrong_answer":"Bent","correct_answer":"Straight"}'::jsonb, 'The child makes a roll shape.', 'Offer "Bent" next to the right answer and ask the question again in a new context.', 'Compare a cartwheel with a bent arm and a straight arm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.GYMNASTICS.CARTWHEEL.M_CW_SEQUENCE', 'CREA.G6.CREATI.GYMNASTICS.CARTWHEEL', 'Puts the sequence in the wrong order.', '{"question":"What is the order of the three actions?","wrong_answer":"Swan balance, cartwheel, forward roll","correct_answer":"Cartwheel, forward roll, swan balance"}'::jsonb, 'The child does not remember the order set in the lesson.', 'Offer "Swan balance, cartwheel, forward roll" next to the right answer and ask the question again in a new context.', 'Write the three actions on cards and put them in order.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.GYMNASTICS.CARTWHEEL.M_CA6_CW_HANDS_TOGETHER', 'CREA.G6.CREATI.GYMNASTICS.CARTWHEEL', 'Places both hands down at the same time in a cartwheel.', '{"question":"In a cartwheel, do both hands go down together?","wrong_answer":"yes","correct_answer":"no; one hand, then the other"}'::jsonb, 'The child copies a handstand.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Walk through hand, hand, foot, foot on lines.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.MELODY.SOLFA.M_ML_ORDER', 'CREA.G6.CREATI.MELODY.SOLFA', 'Swaps neighbouring sol-fa syllables.', '{"question":"Which syllable comes after soh going up?","wrong_answer":"Ti","correct_answer":"Lah"}'::jsonb, 'The child mixes the order of lah and ti.', 'Offer "Ti" next to the right answer and ask the question again in a new context.', 'Sing the ladder up and down several times.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.MELODY.SOLFA.M_ML_DOWN', 'CREA.G6.CREATI.MELODY.SOLFA', 'Says descending means going up.', '{"question":"Which syllable comes first when you sing down from doh1?","wrong_answer":"Re","correct_answer":"Ti"}'::jsonb, 'The child starts from the bottom both ways.', 'Offer "Re" next to the right answer and ask the question again in a new context.', 'Climb a stair as you sing up and walk down as you sing down.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.MELODY.SOLFA.M_ML_SIGN', 'CREA.G6.CREATI.MELODY.SOLFA', 'Shows doh as a finger pointing up, mixing it with the sign for ti.', '{"question":"What is the hand sign for doh?","wrong_answer":"A finger pointing up","correct_answer":"A closed fist"}'::jsonb, 'Ti''s pointing finger is the newest sign learnt, so the child uses it for doh.', 'Offer "A finger pointing up" next to the right answer and ask the question again in a new context.', 'Make the two signs and sing the syllables.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.CREATI.MELODY.SOLFA.M_CA6_ML_TOP_DOH_LOW', 'CREA.G6.CREATI.MELODY.SOLFA', 'Thinks the top doh'' is lower than doh.', '{"question":"Is doh'' higher or lower than doh?","wrong_answer":"lower","correct_answer":"higher, the same note eight steps up"}'::jsonb, 'The child sees the same name and expects the same height, or lower.', 'Offer "lower" next to the right answer and ask the question again in a new context.', 'Sing up the ladder and land on doh''.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.PERFOR.ATHLETICS.JUMPS.M_AJ_TAKEOFF', 'CREA.G6.PERFOR.ATHLETICS.JUMPS', 'Says a long jump is taken off from both feet.', '{"question":"In the long jump, how does the athlete take off?","wrong_answer":"From both feet together","correct_answer":"From one foot"}'::jsonb, 'The child mixes the long jump with the standing jump.', 'Offer "From both feet together" next to the right answer and ask the question again in a new context.', 'Practise a short run-up and take off from one foot.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.PERFOR.ATHLETICS.JUMPS.M_AJ_ORDER', 'CREA.G6.PERFOR.ATHLETICS.JUMPS', 'Puts the phases of the long jump in the wrong order.', '{"question":"What is the first phase of the long jump?","wrong_answer":"Landing","correct_answer":"The run-up"}'::jsonb, 'The child thinks of the jump alone.', 'Offer "Landing" next to the right answer and ask the question again in a new context.', 'Write each phase on a card and put the cards in order.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.PERFOR.ATHLETICS.JUMPS.M_AJ_MEASURE', 'CREA.G6.PERFOR.ATHLETICS.JUMPS', 'Says the jump is measured from where the runner starts or stops.', '{"question":"Where is the long jump measured from?","wrong_answer":"From where the run-up starts","correct_answer":"From the take-off line to the nearest mark in the sand"}'::jsonb, 'The child does not know the measuring rule.', 'Offer "From where the run-up starts" next to the right answer and ask the question again in a new context.', 'Measure a practice jump with a tape.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.PERFOR.ATHLETICS.JUMPS.M_CA6_AJ_TWO_FEET', 'CREA.G6.PERFOR.ATHLETICS.JUMPS', 'Takes off from both feet in the long jump.', '{"question":"In the long jump, do you take off from one foot or two?","wrong_answer":"two feet","correct_answer":"one foot"}'::jsonb, 'Standing jumps use two feet, so the child expects the same.', 'Offer "two feet" next to the right answer and ask the question again in a new context.', 'Run up and take off from the strong foot on the board.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.PERFOR.DESCANT_RECORDER.TECHNIQUE.M_DR_BLOW', 'CREA.G6.PERFOR.DESCANT_RECORDER.TECHNIQUE', 'Says to blow hard for a good sound.', '{"question":"How should you blow into the recorder?","wrong_answer":"As hard as you can","correct_answer":"Gently and steadily"}'::jsonb, 'The child thinks louder is better.', 'Offer "As hard as you can" next to the right answer and ask the question again in a new context.', 'Blow hard and gently and listen to the squeak.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.PERFOR.DESCANT_RECORDER.TECHNIQUE.M_DR_HOLE', 'CREA.G6.PERFOR.DESCANT_RECORDER.TECHNIQUE', 'Says the holes may be covered partly.', '{"question":"How should the finger pads cover the holes?","wrong_answer":"Partly, with the tips","correct_answer":"Fully, with the pads"}'::jsonb, 'The child does not see that air escaping makes a squeak.', 'Offer "Partly, with the tips" next to the right answer and ask the question again in a new context.', 'Cover a hole partly and fully and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.PERFOR.DESCANT_RECORDER.TECHNIQUE.M_DR_HAND', 'CREA.G6.PERFOR.DESCANT_RECORDER.TECHNIQUE', 'Says the right hand is on the top holes.', '{"question":"Which hand is on the top holes?","wrong_answer":"The right hand","correct_answer":"The left hand"}'::jsonb, 'The child mixes the hands.', 'Offer "The right hand" next to the right answer and ask the question again in a new context.', 'Hold a recorder and check which hand is on top.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.PERFOR.DESCANT_RECORDER.TECHNIQUE.M_CA6_DR_LOW_C_BLOW_HARD', 'CREA.G6.PERFOR.DESCANT_RECORDER.TECHNIQUE', 'Blows harder for low C.', '{"question":"How should you blow for low C?","wrong_answer":"harder","correct_answer":"very gently, with every hole sealed"}'::jsonb, 'The child thinks a big note needs big breath.', 'Offer "harder" next to the right answer and ask the question again in a new context.', 'Play low C gently and then hard; hear the squeak.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.PERFOR.INDIGENOUS_KENYAN_INSTRU.ENSEMBLE.M_EN_CAT', 'CREA.G6.PERFOR.INDIGENOUS_KENYAN_INSTRU.ENSEMBLE', 'Sorts an instrument into the wrong kind.', '{"question":"The nyatiti belongs to which kind?","wrong_answer":"Wind","correct_answer":"String"}'::jsonb, 'The child sorts by the community and not by how the sound is made.', 'Offer "Wind" next to the right answer and ask the question again in a new context.', 'Sort five instruments by how the sound is made.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.PERFOR.INDIGENOUS_KENYAN_INSTRU.ENSEMBLE.M_EN_LOUD', 'CREA.G6.PERFOR.INDIGENOUS_KENYAN_INSTRU.ENSEMBLE', 'Says each player should play as loudly as possible.', '{"question":"What should an ensemble player do about loudness?","wrong_answer":"Play as loud as possible","correct_answer":"Balance the loudness with the others"}'::jsonb, 'The child thinks a louder sound shows a better player.', 'Offer "Play as loud as possible" next to the right answer and ask the question again in a new context.', 'Play loud together and soft together and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.PERFOR.INDIGENOUS_KENYAN_INSTRU.ENSEMBLE.M_EN_SOLO', 'CREA.G6.PERFOR.INDIGENOUS_KENYAN_INSTRU.ENSEMBLE', 'Says each player should play his own beat.', '{"question":"What should players keep together in an ensemble?","wrong_answer":"Nothing, each plays his own beat","correct_answer":"A steady beat"}'::jsonb, 'The child does not know what an ensemble is.', 'Offer "Nothing, each plays his own beat" next to the right answer and ask the question again in a new context.', 'Clap in a group, first alone and then together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.PERFOR.INDIGENOUS_KENYAN_INSTRU.ENSEMBLE.M_CA6_EN_NO_LEADER', 'CREA.G6.PERFOR.INDIGENOUS_KENYAN_INSTRU.ENSEMBLE', 'Thinks an ensemble needs no leader or starting signal.', '{"question":"How does an ensemble start together?","wrong_answer":"everyone starts when they want","correct_answer":"a leader gives a signal"}'::jsonb, 'The child thinks each player plays their own part freely.', 'Offer "everyone starts when they want" next to the right answer and ask the question again in a new context.', 'Start a class clap on a count of four.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.PERFOR.INDIGENOUS_KENYAN_CRAFT_.SLAB.M_PS_COIL', 'CREA.G6.PERFOR.INDIGENOUS_KENYAN_CRAFT_.SLAB', 'Says a slab is made of coils or a ball of clay.', '{"question":"What is a slab in pottery?","wrong_answer":"A long coil of clay","correct_answer":"A flat sheet of clay"}'::jsonb, 'The child mixes the slab, coil and pinch methods.', 'Offer "A long coil of clay" next to the right answer and ask the question again in a new context.', 'Roll a ball of clay flat with a rolling pin.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.PERFOR.INDIGENOUS_KENYAN_CRAFT_.SLAB.M_PS_JOIN', 'CREA.G6.PERFOR.INDIGENOUS_KENYAN_CRAFT_.SLAB', 'Says edges join with water alone or with nothing.', '{"question":"How do you join two slabs?","wrong_answer":"Press them together dry","correct_answer":"Scratch the edges, wet them with slip and press"}'::jsonb, 'The child does not know scoring.', 'Offer "Press them together dry" next to the right answer and ask the question again in a new context.', 'Join two pieces dry and then scored with slip, and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.PERFOR.INDIGENOUS_KENYAN_CRAFT_.SLAB.M_PS_DRY', 'CREA.G6.PERFOR.INDIGENOUS_KENYAN_CRAFT_.SLAB', 'Says the item should be dried quickly in the hot sun.', '{"question":"How should a clay item be dried?","wrong_answer":"Quickly in the hot sun","correct_answer":"Slowly in the shade"}'::jsonb, 'The child wants it dry quickly.', 'Offer "Quickly in the hot sun" next to the right answer and ask the question again in a new context.', 'Dry two small tiles, one fast and one slow, and look for cracks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.PERFOR.INDIGENOUS_KENYAN_CRAFT_.SLAB.M_CA6_PS_UNEVEN_SLAB', 'CREA.G6.PERFOR.INDIGENOUS_KENYAN_CRAFT_.SLAB', 'Rolls slabs thick in one place and thin in another.', '{"question":"Why use two guide sticks when rolling a slab?","wrong_answer":"they are not needed","correct_answer":"to keep the slab the same thickness"}'::jsonb, 'The child rolls by eye.', 'Offer "they are not needed" next to the right answer and ask the question again in a new context.', 'Roll with guide sticks and cut to show even thickness.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.PERFOR.SWIMMING.BREASTSTROKE.M_SW_BACK', 'CREA.G6.PERFOR.SWIMMING.BREASTSTROKE', 'Says breaststroke is done on the back.', '{"question":"How does the body lie in breaststroke?","wrong_answer":"On the back","correct_answer":"Flat and face down"}'::jsonb, 'The child mixes breaststroke and backstroke.', 'Offer "On the back" next to the right answer and ask the question again in a new context.', 'Name the four strokes and how the body lies in each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.PERFOR.SWIMMING.BREASTSTROKE.M_SW_KICK', 'CREA.G6.PERFOR.SWIMMING.BREASTSTROKE', 'Says the legs kick up and down.', '{"question":"What kind of kick is used in breaststroke?","wrong_answer":"A flutter kick, up and down","correct_answer":"A frog kick: knees bend, feet turn out, kick back and together"}'::jsonb, 'The child mixes the kick of crawl and breaststroke.', 'Offer "A flutter kick, up and down" next to the right answer and ask the question again in a new context.', 'Sit on a bench and practise both kicks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.PERFOR.SWIMMING.BREASTSTROKE.M_SW_SAFETY', 'CREA.G6.PERFOR.SWIMMING.BREASTSTROKE', 'Says a child may swim alone if he swims well.', '{"question":"When may a child swim?","wrong_answer":"Alone, if he swims well","correct_answer":"Only with a trained adult watching"}'::jsonb, 'The child thinks skill makes it safe.', 'Offer "Alone, if he swims well" next to the right answer and ask the question again in a new context.', 'List the rules of the water with the teacher.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.PERFOR.SWIMMING.BREASTSTROKE.M_CA6_SW_ARMS_PAST_HIPS', 'CREA.G6.PERFOR.SWIMMING.BREASTSTROKE', 'Pulls the arms all the way back to the hips in breaststroke.', '{"question":"In breaststroke, how far back do the arms pull?","wrong_answer":"to the hips","correct_answer":"to the shoulders, then forward again"}'::jsonb, 'The child copies the long pull of front crawl.', 'Offer "to the hips" next to the right answer and ask the question again in a new context.', 'Practise a small heart-shaped pull on land.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.APPREC.ANALYSIS_OF_CREATIVE_ART.ELEMENTS.M_AE_TEMPO', 'CREA.G6.APPREC.ANALYSIS_OF_CREATIVE_ART.ELEMENTS', 'Says tempo is how loud the music is.', '{"question":"What is tempo?","wrong_answer":"How loud or soft the music is","correct_answer":"How fast or slow the music is"}'::jsonb, 'The child mixes tempo and dynamics.', 'Offer "How loud or soft the music is" next to the right answer and ask the question again in a new context.', 'Clap fast, slow, loud and soft and name each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.APPREC.ANALYSIS_OF_CREATIVE_ART.ELEMENTS.M_AE_PITCH', 'CREA.G6.APPREC.ANALYSIS_OF_CREATIVE_ART.ELEMENTS', 'Says pitch is how loud a sound is.', '{"question":"What is pitch?","wrong_answer":"How loud a sound is","correct_answer":"How high or low a sound is"}'::jsonb, 'The child mixes pitch and loudness.', 'Offer "How loud a sound is" next to the right answer and ask the question again in a new context.', 'Sing a high and a low note and name them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.APPREC.ANALYSIS_OF_CREATIVE_ART.ELEMENTS.M_AE_MESSAGE', 'CREA.G6.APPREC.ANALYSIS_OF_CREATIVE_ART.ELEMENTS', 'Says the message of a song is its tune.', '{"question":"What is the message of a song?","wrong_answer":"The tune","correct_answer":"What the words teach or say"}'::jsonb, 'The child mixes the message and the music.', 'Offer "The tune" next to the right answer and ask the question again in a new context.', 'Read the words of a song without the tune and ask what they say.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.APPREC.ANALYSIS_OF_CREATIVE_ART.CATALOGUE.M_AC_STORY', 'CREA.G6.APPREC.ANALYSIS_OF_CREATIVE_ART.CATALOGUE', 'Says a catalogue is a story about the artist.', '{"question":"What is a catalogue of an exhibition?","wrong_answer":"A story about the artist","correct_answer":"A list of the artworks with details"}'::jsonb, 'The child does not know the word.', 'Offer "A story about the artist" next to the right answer and ask the question again in a new context.', 'Show a real exhibition list.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.APPREC.ANALYSIS_OF_CREATIVE_ART.CATALOGUE.M_AC_ENTRY', 'CREA.G6.APPREC.ANALYSIS_OF_CREATIVE_ART.CATALOGUE', 'Puts the visitor''s name in a catalogue entry instead of the title and the artist.', '{"question":"Which detail belongs in a catalogue entry?","wrong_answer":"The visitor''s name","correct_answer":"The title and the artist"}'::jsonb, 'The child mixes a catalogue with a visitors'' book, both kept at an exhibition.', 'Offer "The visitor''s name" next to the right answer and ask the question again in a new context.', 'Write an entry for one artwork.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.APPREC.ANALYSIS_OF_CREATIVE_ART.CATALOGUE.M_AC_PURPOSE', 'CREA.G6.APPREC.ANALYSIS_OF_CREATIVE_ART.CATALOGUE', 'Says a catalogue is for hiding the artworks or only for the teacher.', '{"question":"Why is a catalogue made?","wrong_answer":"To keep the artworks secret","correct_answer":"To help visitors find and understand the works"}'::jsonb, 'The child does not see who the catalogue is for.', 'Offer "To keep the artworks secret" next to the right answer and ask the question again in a new context.', 'Walk through an exhibition with and without a list.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.APPREC.ANALYSIS_OF_CREATIVE_ART.ELEMENTS.M_CA6_AE_DYNAMICS_SPEED', 'CREA.G6.APPREC.ANALYSIS_OF_CREATIVE_ART.ELEMENTS', 'Calls a change in speed a change in dynamics.', '{"question":"A song gets faster. Which element changed?","wrong_answer":"dynamics","correct_answer":"tempo"}'::jsonb, 'Both make a song feel more exciting.', 'Offer "dynamics" next to the right answer and ask the question again in a new context.', 'Sing louder, then faster; name each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G6.APPREC.ANALYSIS_OF_CREATIVE_ART.CATALOGUE.M_CA6_AC_ORDER', 'CREA.G6.APPREC.ANALYSIS_OF_CREATIVE_ART.CATALOGUE', 'Lists catalogue entries in any order with no numbers.', '{"question":"Why are catalogue entries numbered?","wrong_answer":"they do not need numbers","correct_answer":"so visitors can match each entry to the work on display"}'::jsonb, 'The child thinks a catalogue is only a list of names.', 'Offer "they do not need numbers" next to the right answer and ask the question again in a new context.', 'Number the works and the entries to match.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
